    "options": [
      {
        "id": "A",
        "text": "<p style=\"text-align: left;\">The value of <math alttext=\"x\"><mi>x</mi></math> is less than <math alttext=\"145\"><mn>145</mn></math>.</p>"
      },
      {
        "id": "B",
        "text": "<p style=\"text-align: left;\">The value of <math alttext=\"x\"><mi>x</mi></math> is greater than <math alttext=\"145\"><mn>145</mn></math>.</p>"
      },
      {
        "id": "C",
        "text": "<p style=\"text-align: left;\">The value of <math alttext=\"x\"><mi>x</mi></math> is equal to <math alttext=\"145\"><mn>145</mn></math>.</p>"
      },
      {
        "id": "D",
        "text": "<p style=\"text-align: left;\">The value of <math alttext=\"x\"><mi>x</mi></math> cannot be determined.</p>"
      }
    ]
